// Acceptance (roadmap Q6, errors): a degraded Hono dashboard widget logs
// one console.warn/console.info line carrying the widget name and the
// request's correlation id, so a degraded 200 is distinguishable from a
// healthy one. Healthy renders stay silent and the outage 503 is unchanged;
// no markup change. Failing-first: the widget-line assertions fail until the
// Q6 build lands. Owned by the Test Author: do not edit this file on the
// build card — return incorrect tests to the Test Author instead.
import { drizzle } from "drizzle-orm/postgres-js";
import { serializeSigned } from "hono/utils/cookie";
import { Hono } from "hono";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import * as funnel from "../src/admin/join-funnel";
import { adminApp } from "../src/admin/routes";
import type { Db } from "../src/db/index";
import type { Env } from "../src/env";
import { requestLog } from "../src/request-log";
import { createMemorySessionStore, hashToken, newSessionToken } from "../src/sessions";

vi.mock("../src/admin/writeback", () => ({ dispatchWriteBack: vi.fn() }));

const RAY = "0123456789abcdef-LHR";
const SESSION_SECRET = "test-session-secret-at-least-32-bytes-long";
const env: Env = {
  APP_URL: "https://next.example.test",
  DISCORD_CLIENT_ID: "client-id",
  DISCORD_GUILD_ID: "326474832151838730",
  DISCORD_INVITE_URL: "https://discord.gg/invite",
  DISCORD_CLIENT_SECRET: "client-secret",
  DISCORD_BOT_TOKEN: "bot-token",
  SESSION_SECRET,
};

function aggregateDb(n: number) {
  const aggregate = vi.fn(async () => [{ outcome: "added", n }]);
  const db = drizzle.mock() as unknown as Db;
  const session = (
    db as unknown as {
      session: {
        prepareQuery: (query: { sql: string }) => unknown;
        transaction: (work: (tx: Db) => Promise<unknown>) => Promise<unknown>;
      };
    }
  ).session;
  session.prepareQuery = (query) => ({
    setToken() {
      return this;
    },
    execute: async () => {
      if (query.sql.includes('from "join_attempts"')) return aggregate();
      if (
        query.sql.includes('from "event_search_logs"') ||
        query.sql.startsWith("select set_config(")
      )
        return [];
      throw new Error("Dashboard query has no isolated fixture");
    },
  });
  session.transaction = async (work) => work(db);
  return { db, aggregate, session };
}

async function cookieFor(store: ReturnType<typeof createMemorySessionStore>) {
  const token = newSessionToken();
  await store.create({
    tokenHash: await hashToken(token),
    userId: "100000000000000111",
    username: "mod",
    avatar: null,
    member: true,
    moderator: true,
    expiresAt: new Date(Date.now() + 3600_000),
  });
  const s = await serializeSigned("__Host-two_session", token, SESSION_SECRET, {
    path: "/",
    secure: true,
    httpOnly: true,
    sameSite: "Lax",
  });
  return s.split(";")[0]!;
}

/** The production mount runs requestLog ahead of the admin routes. */
function dashboardApp(store: ReturnType<typeof createMemorySessionStore>) {
  const router = new Hono<{ Bindings: Env }>();
  router.use("*", requestLog);
  router.route("/", adminApp({ sessionStore: store }));
  return router;
}

/** Serialized console.warn/console.info lines mentioning the widget. */
function widgetLines(pattern: RegExp): string[] {
  const out: string[] = [];
  for (const spy of [vi.mocked(console.warn), vi.mocked(console.info)]) {
    for (const call of spy.mock.calls) {
      const line = call
        .map((arg) => (typeof arg === "string" ? arg : (JSON.stringify(arg) ?? String(arg))))
        .join(" ");
      if (pattern.test(line)) out.push(line);
    }
  }
  return out;
}

const cancellation = () =>
  Object.assign(new Error("statement timeout"), {
    code: "57014",
    name: "PostgresError",
  });

describe("degraded Hono dashboard widgets log one correlated line", () => {
  beforeEach(() => {
    vi.spyOn(console, "log").mockImplementation(() => {});
    vi.spyOn(console, "warn").mockImplementation(() => {});
    vi.spyOn(console, "info").mockImplementation(() => {});
    vi.spyOn(console, "error").mockImplementation(() => {});
  });
  afterEach(() => vi.restoreAllMocks());

  it("a cancelled zero-search widget logs one line with the widget name and request_id", async () => {
    // Real helpers, no mocks: the zero-search read rejects with a 57014
    // cancellation (classified unavailable, so it propagates out of the
    // helper) and the route swallows it into an omitted section. The funnel
    // transaction runs first and stays healthy.
    const store = createMemorySessionStore();
    const { db, session } = aggregateDb(7);
    let calls = 0;
    const realTransaction = session.transaction;
    session.transaction = async (work) => {
      if (++calls === 1) return realTransaction(work);
      throw cancellation();
    };
    const res = await dashboardApp(store).request(
      "/",
      { headers: { cookie: await cookieFor(store), "cf-ray": RAY } },
      { ...env, ADMIN_DB: db } as Env,
    );
    expect(res.status).toBe(200);
    expect(res.headers.get("x-request-id")).toBe(RAY);
    const html = await res.text();
    expect(html).toContain('data-testid="join-funnel"');
    expect(html).not.toContain('data-testid="top-zero-searches"');
    const lines = widgetLines(/zero.?searches/i);
    expect(lines).toHaveLength(1);
    expect(lines[0]).toContain(RAY);
  });

  it("a cancelled funnel widget logs one line with the widget name and request_id", async () => {
    // Settlement contract, not helper behavior: the real funnel helper
    // resolves undefined on cancellation, so only a rejected settlement
    // exercises the route's log line. The mock stands in for that settlement.
    vi.spyOn(funnel, "dashboardJoinFunnel").mockRejectedValueOnce(cancellation());
    const store = createMemorySessionStore();
    const { db } = aggregateDb(7);
    const res = await dashboardApp(store).request(
      "/",
      { headers: { cookie: await cookieFor(store), "cf-ray": RAY } },
      { ...env, ADMIN_DB: db } as Env,
    );
    expect(res.status).toBe(200);
    expect(res.headers.get("x-request-id")).toBe(RAY);
    const html = await res.text();
    expect(html).not.toContain('data-testid="join-funnel"');
    expect(html).toContain('data-testid="top-zero-searches"');
    const lines = widgetLines(/funnel/i);
    expect(lines).toHaveLength(1);
    expect(lines[0]).toContain(RAY);
  });

  it("healthy widgets log no widget lines (control)", async () => {
    const store = createMemorySessionStore();
    const { db } = aggregateDb(7);
    const res = await dashboardApp(store).request(
      "/",
      { headers: { cookie: await cookieFor(store), "cf-ray": RAY } },
      { ...env, ADMIN_DB: db } as Env,
    );
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html).toContain('data-testid="join-funnel"');
    expect(html).toContain('data-testid="top-zero-searches"');
    expect(widgetLines(/funnel|zero.?searches/i)).toEqual([]);
  });

  it("a refused widget keeps the 503 outage (control)", async () => {
    const store = createMemorySessionStore();
    const { db, session } = aggregateDb(7);
    session.transaction = async () => {
      throw Object.assign(new Error("connection refused"), { code: "ECONNREFUSED" });
    };
    const res = await dashboardApp(store).request(
      "/",
      { headers: { cookie: await cookieFor(store), "cf-ray": RAY } },
      { ...env, ADMIN_DB: db } as Env,
    );
    expect(res.status).toBe(503);
    expect(await res.text()).toContain("We will be right back");
  });
});
